class OutboxProcessor {
  async processOutbox() {
    while (true) {
      // Fetch unpublished events in batches
      const events = await db.query(
        'SELECT * FROM outbox WHERE published_at IS NULL ORDER BY created_at LIMIT 100'
      );

      if (events.length === 0) {
        await sleep(1000);
        continue;
      }

      for (const event of events) {
        try {
          await kafka.send({
            topic: event.aggregate_type,
            messages: [{ key: event.aggregate_id, value: event.payload }]
          });

          // Mark as published
          await db.query(
            'UPDATE outbox SET published_at = NOW() WHERE id = $1',
            [event.id]
          );
        } catch (error) {
          await sleep(5000); // Retry after delay
          break;
        }
      }
    }
  }
}
